from typing import List

def maxAlternatingSum(nums: List[int], swaps: List[List[int]]) -> int:
    n = len(nums)
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    for a, b in swaps:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(i)
    total = 0
    for idxs in comps.values():
        plus = sum(1 for i in idxs if i % 2 == 0)
        vals = sorted((nums[i] for i in idxs), reverse=True)
        for p, v in enumerate(vals):
            if p < plus:
                total += v
            else:
                total -= v
    return total
